#!/bin/bash
# ============================================================================
# FFT with SYCL + oneMKL + MPI - High-performance distributed FFT stack
# Creates a complete project in ~/fft_sycl_project
# ============================================================================

set -e

PROJECT_DIR="$HOME/fft_sycl_project"
mkdir -p "$PROJECT_DIR/src" "$PROJECT_DIR/scripts"

cd "$PROJECT_DIR"

# ----------------------------------------------------------------------------
# CMakeLists.txt
# ----------------------------------------------------------------------------
cat > CMakeLists.txt << 'EOF'
cmake_minimum_required(VERSION 3.15)
project(FFT_SYCL_MPI LANGUAGES CXX)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)

# Find MPI
find_package(MPI REQUIRED)

# Find SYCL (DPC++ or hipSYCL)
# For DPC++, set CMAKE_CXX_COMPILER to dpcpp
# For hipSYCL, set SYCL_IMPLEMENTATION to hipsycl
find_package(SYCL REQUIRED)

# Find oneMKL
find_package(MKL REQUIRED)

add_executable(fft_sycl_mpi src/main.cpp)

target_link_libraries(fft_sycl_mpi
    PRIVATE
    MPI::MPI_CXX
    SYCL::SYCL
    MKL::MKL
)

# Optional: compile with -O3 and debug info
target_compile_options(fft_sycl_mpi PRIVATE -O3 -g)

# Install to bin (optional)
install(TARGETS fft_sycl_mpi DESTINATION bin)
EOF

# ----------------------------------------------------------------------------
# src/main.cpp – Distributed 1D FFT using oneMKL SYCL interface
# ----------------------------------------------------------------------------
cat > src/main.cpp << 'EOF'
#include <mpi.h>
#include <CL/sycl.hpp>
#include <oneapi/mkl.hpp>

#include <iostream>
#include <vector>
#include <cmath>
#include <complex>
#include <algorithm>
#include <numeric>
#include <cassert>

using namespace sycl;

// ----------------------------------------------------------------------
// Custom dispatcher: currently only oneMKL, but extensible to other backends
// ----------------------------------------------------------------------
namespace fft_dispatcher {

template <typename T>
class FFTPlan {
public:
    using complex_t = std::complex<T>;

    FFTPlan(queue& q, size_t n, bool inplace = true)
        : q_(q), n_(n), inplace_(inplace) {
        // Create descriptor
        desc_ = oneapi::mkl::dft::descriptor<
            std::conditional_t<std::is_same_v<T, float>,
                               oneapi::mkl::dft::precision::SINGLE,
                               oneapi::mkl::dft::precision::DOUBLE>,
            oneapi::mkl::dft::domain::COMPLEX>(n_);
        desc_.set_value(oneapi::mkl::dft::config_value::PLACEMENT,
                        inplace_ ? oneapi::mkl::dft::config_value::INPLACE
                                 : oneapi::mkl::dft::config_value::OUTOFPLACE);
        oneapi::mkl::dft::commit(desc_, q_);
    }

    void forward(complex_t* data) {
        oneapi::mkl::dft::compute_forward(desc_, data);
    }

    void backward(complex_t* data) {
        oneapi::mkl::dft::compute_backward(desc_, data);
    }

    // Out-of-place versions (if needed)
    void forward(complex_t* in, complex_t* out) {
        if (inplace_) {
            forward(in);
        } else {
            oneapi::mkl::dft::compute_forward(desc_, in, out);
        }
    }

    void backward(complex_t* in, complex_t* out) {
        if (inplace_) {
            backward(in);
        } else {
            oneapi::mkl::dft::compute_backward(desc_, in, out);
        }
    }

    size_t size() const { return n_; }

private:
    queue& q_;
    size_t n_;
    bool inplace_;
    oneapi::mkl::dft::descriptor<oneapi::mkl::dft::precision::SINGLE,
                                 oneapi::mkl::dft::domain::COMPLEX> desc_;
};

} // namespace fft_dispatcher

// ----------------------------------------------------------------------
// Main: MPI + SYCL + oneMKL FFT
// ----------------------------------------------------------------------
int main(int argc, char* argv[]) {
    MPI_Init(&argc, &argv);

    int rank, nRanks;
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &nRanks);

    // Total problem size (must be divisible by nRanks)
    const size_t N_TOTAL = 1 << 12; // 4096
    if (N_TOTAL % nRanks != 0) {
        if (rank == 0)
            std::cerr << "Error: N_TOTAL must be divisible by number of ranks.\n";
        MPI_Abort(MPI_COMM_WORLD, 1);
    }
    const size_t N_LOCAL = N_TOTAL / nRanks;

    // Select default SYCL device
    default_selector selector;
    queue q(selector, property::queue::in_order());
    if (rank == 0) {
        std::cout << "Device: " << q.get_device().get_info<info::device::name>() << "\n";
        std::cout << "Total FFT size: " << N_TOTAL
                  << " (local per rank: " << N_LOCAL << ")\n";
    }

    // Use single-precision complex
    using T = float;
    using complex_t = std::complex<T>;

    // Host data
    std::vector<complex_t> h_input(N_LOCAL);
    // Initialize with a simple signal: linear ramp + imaginary part
    for (size_t i = 0; i < N_LOCAL; ++i) {
        T val = static_cast<T>(i + rank * N_LOCAL);
        h_input[i] = complex_t(val, 0.0f);
    }

    // Allocate USM shared memory (accessible from host and device)
    complex_t* d_data = malloc_shared<complex_t>(N_LOCAL, q);
    if (!d_data) {
        std::cerr << "Rank " << rank << " failed to allocate USM memory.\n";
        MPI_Abort(MPI_COMM_WORLD, 2);
    }

    // Copy input to device
    q.memcpy(d_data, h_input.data(), N_LOCAL * sizeof(complex_t)).wait();

    // Create FFT plan (in-place)
    fft_dispatcher::FFTPlan<T> plan(q, N_LOCAL, true);

    // Forward transform
    plan.forward(d_data);
    q.wait();

    // Backward transform
    plan.backward(d_data);
    q.wait();

    // Copy result back to host
    q.memcpy(h_input.data(), d_data, N_LOCAL * sizeof(complex_t)).wait();

    // Verify: backward(forward(x)) should equal x * N_LOCAL
    bool ok = true;
    const T tol = 1e-4f;
    for (size_t i = 0; i < N_LOCAL && ok; ++i) {
        T expected = static_cast<T>(i + rank * N_LOCAL) * N_LOCAL;
        T got = h_input[i].real();
        if (std::abs(got - expected) > tol) {
            ok = false;
            if (rank == 0)
                std::cerr << "Mismatch at local index " << i
                          << ": expected " << expected << ", got " << got << "\n";
        }
    }

    // All ranks must agree
    int all_ok = ok ? 1 : 0;
    int global_ok = 0;
    MPI_Allreduce(&all_ok, &global_ok, 1, MPI_INT, MPI_MIN, MPI_COMM_WORLD);

    if (rank == 0) {
        if (global_ok)
            std::cout << "FFT test PASSED on all ranks.\n";
        else
            std::cout << "FFT test FAILED on at least one rank.\n";
    }

    // Free device memory
    free(d_data, q);

    MPI_Finalize();
    return 0;
}
EOF

# ----------------------------------------------------------------------------
# src/fft_dispatcher.hpp – (optional) could be expanded for multi-backend
# We already inlined it in main.cpp, but we create a header for extensibility
# ----------------------------------------------------------------------------
cat > src/fft_dispatcher.hpp << 'EOF'
#pragma once
// Placeholder for a more advanced dispatcher that could switch between
// oneMKL, rocFFT, cuFFT, or even FFTW based on runtime device detection.
// Currently we use oneMKL directly.
// This file can be extended without modifying main.cpp.
EOF

# ----------------------------------------------------------------------------
# scripts/compile_run.sh – One‑click build and execution
# ----------------------------------------------------------------------------
cat > scripts/compile_run.sh << 'EOF'
#!/bin/bash
# Usage: ./compile_run.sh [number_of_ranks]
# Default ranks = 2

set -e

RANKS=${1:-2}
BUILD_DIR="build"

# Detect if we are in the project root
if [ ! -d "src" ] || [ ! -f "CMakeLists.txt" ]; then
    echo "Please run from the project root directory."
    exit 1
fi

mkdir -p "$BUILD_DIR"
cd "$BUILD_DIR"

# Configure with CMake – adjust compiler if needed
# For DPC++: set CC=icx CXX=icpx or use dpcpp directly
# Example: CXX=dpcpp cmake ..
cmake .. -DCMAKE_CXX_COMPILER=dpcpp

# Build
make -j$(nproc)

# Run with MPI
echo "Running with $RANKS MPI ranks..."
mpirun -np "$RANKS" ./fft_sycl_mpi
EOF

chmod +x scripts/compile_run.sh

# ----------------------------------------------------------------------------
# README.md – short guide
# ----------------------------------------------------------------------------
cat > README.md << 'EOF'
# SYCL + oneMKL + MPI FFT Example

This project demonstrates a high‑performance, device‑agnostic FFT stack using:
- **C++** for zero‑cost abstractions
- **SYCL** for single‑source heterogeneous programming
- **Intel oneMKL** (SYCL interfaces) for vendor‑optimized FFTs
- **MPI** for distributed‑memory parallelism

## Requirements
- A SYCL implementation (Intel DPC++, hipSYCL, or ComputeCpp)
- Intel oneMKL (or a compatible library exposing the SYCL DFT interface)
- MPI (e.g., OpenMPI)

## Build & Run
```bash
cd ~/fft_sycl_project
./scripts/compile_run.sh [number_of_ranks]
```

## Customisation
- Change `N_TOTAL` in `src/main.cpp` for a different problem size.
- The dispatcher in `fft_dispatcher` can be extended to other backends (rocFFT, cuFFT, FFTW) by detecting the vendor at runtime.
EOF

# ----------------------------------------------------------------------------
# Final message
# ----------------------------------------------------------------------------
echo ""
echo "============================================================"
echo "Project created in: $PROJECT_DIR"
echo "To compile and run:"
echo "  cd $PROJECT_DIR"
echo "  ./scripts/compile_run.sh [num_ranks]"
echo ""
echo "Example: ./scripts/compile_run.sh 4"
echo "============================================================"
```

